var ids={"bf-stamp": "ah-live-bf-stamp", "bf-shelters": "ah-live-bf-shelters", "bf-feed": "ah-live-bf-feed", "bf-breeders": "ah-live-bf-breeders"};function ahToolElement(id){return document.getElementById(ids[id]||id);}
(function () {
  var DATA_URL = "https://gaughanadrienne-gif.github.io/ah-graphics/build-your-flock-data.json";
  var LIVE_CAP = 12; // max individual live items shown per high-volume source

  var ICONS = {
    chicken: '<svg class="bf-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M15 3a2.5 2.5 0 0 0-2.45 2H12a6 6 0 0 0-6 6v1a5 5 0 0 0 5 5h1a5 5 0 0 0 5-5V8.6A3.5 3.5 0 0 0 16 6l2-1-2.4-.8A2.5 2.5 0 0 0 15 3zm-3 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2z"/></svg>',
    duck: '<svg class="bf-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M16 4a3 3 0 0 0-3 3H8.5a4.5 4.5 0 0 0 0 9H11c3.3 0 6-2.7 6-6V7.5l2.5-1L17 5.4A3 3 0 0 0 16 4zm-1 4a1 1 0 1 1 0-2 1 1 0 0 1 0 2z"/></svg>',
    goose: '<svg class="bf-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M13 2a3 3 0 0 0-3 3v2.2A6 6 0 0 0 6 13a6 6 0 0 0 6 6h1a5 5 0 0 0 5-5V5a3 3 0 0 0-3-3h-2zm0 5a1 1 0 1 1 0-2 1 1 0 0 1 0 2z"/></svg>'
  };
  function esc(s){ var d=document.createElement('div'); d.textContent = (s==null?'':String(s)); return d.innerHTML; }
  function icon(a){ return ICONS[a] || ICONS.chicken; }
  function titleCase(s){ return (s||'').toLowerCase().replace(/\b\w/g, function(c){ return c.toUpperCase(); }); }

  // Distill a clean one-line summary. SCCAS (24PetConnect) detail is a verbose dump
  // ("Name : X Gender : Male Breed : Chicken Age : 8 months old Weight : ..."); Petfinder
  // detail is already concise ("Chicken in Monterey, CA").
  function shelterDetail(r){
    var d = r.detail || '';
    if (!/Breed\s*:/i.test(d)) return d || titleCase(r.animal);
    var field = function(label){
      var m = d.match(new RegExp(label + '\\s*:\\s*([^:]*?)(?:\\s+[A-Z][A-Za-z/]+\\s*:|$)'));
      return m ? m[1].trim() : '';
    };
    var gender = field('Gender'); if (/unknown/i.test(gender)) gender = '';
    var breed = field('Breed');
    var age = field('Age'); if (/unknown/i.test(age)) age = '';
    var lead = [gender, breed].filter(Boolean).join(' ');
    return [lead, age].filter(Boolean).join(', ') || titleCase(r.animal);
  }

  function shelterCard(r){
    return '<div class="bf-card"><div class="bf-card-head">'+icon(r.animal)+
      '<h4>'+esc(titleCase(r.name))+'</h4></div>'+
      '<div class="bf-meta">'+esc(shelterDetail(r))+'</div>'+
      '<div class="bf-src">'+esc(r.source)+'</div>'+
      '<a class="bf-link" href="'+esc(r.link)+'" target="_blank" rel="noopener">View listing &rarr;</a></div>';
  }

  function curatedCard(c){
    var photo = c.photo ? '<img class="bf-photo" src="'+esc(c.photo)+'" alt="'+esc(c.source)+'">' : '';
    var head = '<div class="bf-card-head">'+(c.photo?'':icon('chicken'))+'<h4>'+esc(c.source)+'</h4></div>';
    var loc = c.location ? '<div class="bf-src">'+esc(c.location)+'</div>' : '';
    return '<div class="bf-card">'+photo+head+loc+
      '<div class="bf-meta">'+esc(c.blurb)+'</div>'+
      '<a class="bf-link" href="'+esc(c.link)+'" target="_blank" rel="noopener">Learn more &rarr;</a></div>';
  }

  // Summary card for a high-volume live source (Scotts Valley chicks, Metzer breeds).
  function summaryCard(opts){
    // opts: {title, source, location, link, linkText, items:[{label, sub, status}], total}
    var rows = opts.items.map(function(it){
      var badge = it.status ? '<span class="bf-badge '+esc(it.status.toLowerCase().split(' ')[0])+'">'+esc(it.statusLabel||it.status)+'</span>' : '';
      var sub = it.sub ? '<span class="bf-meta">'+esc(it.sub)+'</span>' : '';
      return '<li><span class="bf-li-name">'+esc(it.label)+'</span>'+sub+badge+'</li>';
    }).join('');
    var more = (opts.total > opts.items.length)
      ? '<div class="bf-more">+ '+(opts.total - opts.items.length)+' more at '+esc(opts.source)+'</div>' : '';
    var loc = opts.location ? '<div class="bf-src">'+esc(opts.location)+'</div>' : '';
    return '<div class="bf-card bf-wide"><div class="bf-card-head">'+icon(opts.animal||'chicken')+
      '<h4>'+esc(opts.title)+'</h4></div>'+loc+
      (opts.subtitle?'<div class="bf-meta">'+esc(opts.subtitle)+'</div>':'')+
      '<ul class="bf-list">'+rows+'</ul>'+more+
      '<a class="bf-link" href="'+esc(opts.link)+'" target="_blank" rel="noopener">'+esc(opts.linkText||'View all')+' &rarr;</a></div>';
  }

  function renderSection(el, title, subhead, html, emptyMsg){
    if(!html){ html = '<div class="bf-empty">'+esc(emptyMsg)+'</div>'; }
    el.innerHTML = '<h3>'+esc(title)+'</h3>'+
      (subhead?'<div class="bf-subhead">'+esc(subhead)+'</div>':'')+
      '<div class="bf-grid">'+html+'</div>';
  }

  function feedSummary(items){
    // Show available (in-stock/incoming) chicks; if all sold out, say so.
    var avail = items.filter(function(i){ return i.status==='in-stock' || i.status==='incoming'; });
    if(!avail.length) return '';
    var shown = avail.slice(0, LIVE_CAP);
    return summaryCard({
      title:'Scotts Valley Feed', source:'Scotts Valley Feed', location:'Scotts Valley, CA',
      subtitle:"This season's chicks (call the day before to confirm arrivals).",
      link:'https://www.scottsvalleyfeed.com/chicks', linkText:'See the full chick schedule',
      total: avail.length,
      items: shown.map(function(i){
        return { label:i.breed, sub:[i.price, i.date].filter(Boolean).join('  '), status:i.status,
                 statusLabel: i.status==='incoming'?'Incoming':'In stock' };
      })
    });
  }

  function metzerSummary(items){
    var counts = items.reduce(function(a,i){ a[i.animal]=(a[i.animal]||0)+1; return a; }, {});
    var order = {goose:0, duck:1, chicken:2}; // surface waterfowl first (the unique value)
    var sorted = items.slice().sort(function(a,b){ return (order[a.animal]||9)-(order[b.animal]||9); });
    var shown = sorted.slice(0, LIVE_CAP);
    var parts = [];
    if(counts.duck) parts.push(counts.duck+' duck');
    if(counts.goose) parts.push(counts.goose+' goose');
    if(counts.chicken) parts.push(counts.chicken+' chicken');
    return summaryCard({
      title:'Metzer Farms', source:'Metzer Farms', location:'Gonzales, CA  (ships ducklings & goslings)',
      animal:'duck',
      subtitle: parts.join(', ')+' options with upcoming hatch dates. Listings may include different sexes of the same breed.',
      link:'https://www.metzerfarms.com/available.html', linkText:'See full availability',
      total: items.length,
      items: shown.map(function(i){
        var st = (i.status||'').toLowerCase();
        var cls = st.indexOf('limited')>-1 ? 'limited' : (st.indexOf('sold')>-1 ? 'sold-out' : 'available');
        return { label:i.breed, sub:titleCase(i.animal), status:cls,
                 statusLabel: i.status };
      })
    });
  }

  function render(data){
    var s = data.sections;
    var stamp = ahToolElement('bf-stamp');
    var when = new Date(data.updated);
    stamp.textContent = isNaN(when) ? 'Availability updates daily'
      : 'Last updated: ' + when.toLocaleDateString('en-US', {month:'long', day:'numeric', year:'numeric'});

    // A successful feed build does not mean every supplier refreshed successfully.
    var sourceKeys = {'Santa Cruz County Animal Shelter':'sccas', 'Scotts Valley Feed':'scotts_valley',
      'Alchemist Farm':'alchemist', 'Metzer Farms':'metzer'};
    var errors = (data.status && data.status.scrapeErrors) || [];
    function failed(source){
      var state = data.status && data.status.sources && data.status.sources[source];
      return (state && state.available === false) || errors.some(function(e){
        return String(e).indexOf(sourceKeys[source] + ':') === 0;
      });
    }
    function current(records){ return records.filter(function(r){ return !r.stale && !failed(r.source); }); }
    function notices(records){
      return Object.keys(sourceKeys).filter(function(source){
        return failed(source) && records.indexOf(source) > -1;
      }).map(function(source){
        return '<div class="bf-card"><h4>'+esc(source)+'</h4><p class="bf-meta">Current availability could not be verified. Check the supplier directly for birds, prices, and dates.</p></div>';
      }).join('');
    }

    // Shelters: individual cards (low volume)
    renderSection(ahToolElement('bf-shelters'), 'Shelters and Rescues', '',
      current(s.shelters.live).map(shelterCard).join('') + s.shelters.curated.map(curatedCard).join('') + notices(['Santa Cruz County Animal Shelter']),
      'No birds listed at local shelters today. Check back soon.');

    // Feed stores: Scotts Valley summary (or seasonal message) + curated
    var feedHtml = feedSummary(current(s.feedStores.live)) + s.feedStores.curated.map(curatedCard).join('') + notices(['Scotts Valley Feed']);
    var feedEmpty = (data.status && data.status.scottsValley === 'off-season')
      ? 'Chick season runs March through August. Check back in spring for arrivals.'
      : 'No chick arrivals posted right now. Call your local feed store for the latest.';
    renderSection(ahToolElement('bf-feed'), 'Feed Stores (Chick Season)', '', feedHtml, feedEmpty);

    // Breeders: Metzer summary + curated breeders/sellers
    var metzerItems = current(s.breeders.live).filter(function(i){ return i.source === 'Metzer Farms'; });
    var breederHtml = (metzerItems.length ? metzerSummary(metzerItems) : '') +
      s.breeders.curated.map(curatedCard).join('') + notices(['Alchemist Farm', 'Metzer Farms']);
    renderSection(ahToolElement('bf-breeders'), 'Breeders and Sellers', '', breederHtml,
      'No breeder listings available right now.');
  }

  // Preview/test hook: if data is injected on the page, render it directly (used for local testing).
  if (window.__BF_DATA) {
    try { render(window.__BF_DATA); } catch (e) { /* leave loading stamp */ }
    return;
  }

  fetch(DATA_URL, {cache:'no-store'})
    .then(function(r){ if(!r.ok) throw new Error('fetch failed'); return r.json(); })
    .then(render)
    .catch(function(){
      ahToolElement('bf-stamp').textContent = 'Availability is being updated. Please check back shortly.';
    });
})();

